head.script:
// 테스트 설명, 유효성 값 설정
//  - 본 샘플(_2) : FilterList 필터(GridView useFilterList=true) 에서 아이템 정의 방식(정적 아이템 / BindItemset) 에 따른 동작
//    inputType / useFilter / delimiter / CustomFilter 기준 표시 형식은 column_P_filterDisplayMode_1 소유
scwin.tData = {
    "description" : "[column > P > filterDisplayMode]<br/>Header Column 의 필터 기능(CustomFilter, FilterList)에서 필터 항목이 표시되는 형식을 설정합니다.",
    "validation" : [
        "GridView 의 useFilterList='true' 로 FilterList 필터가 적용된 경우엔 아이템이 BindItemset 으로 정의된 경우에만 동작합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_filterDisplayMode.setValue("value delim label");
    con_itemType.setValue("itemset");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 아이템 : 서울(SEL) / 부산(BSN) / 대구(DGU) / 인천(ICN)
//  - city Column 데이터는 SEL / BSN / ICN 이므로 필터 항목은 데이터에 있는 3개 값만 표시됨
scwin.itemList = [
    { "label" : "서울", "value" : "SEL" },
    { "label" : "부산", "value" : "BSN" },
    { "label" : "대구", "value" : "DGU" },
    { "label" : "인천", "value" : "ICN" }
];



// comp 생성
//  - GridView useFilterList="true", Header Column(column2) useFilter="true" 고정
//  - city : 검증 대상 Body Column (inputType="select", delimiter=":" 고정 / filterDisplayMode, 아이템 정의 방식 = con 값)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof dlt_item !== 'undefined' && dlt_item) {
        $p.data.remove("dlt_item");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cFilterDisplayMode = con_filterDisplayMode.getValue();
    let cItemType = con_itemType.getValue();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] GridView useFilterList=true, city Column 은 inputType=select, delimiter=: 고정\ncity Column 아이템 : 서울(SEL) / 부산(BSN) / 대구(DGU) / 인천(ICN), 데이터 : SEL / BSN / ICN\n[절차] city Header 필터 버튼 클릭 -> FilterList 목록 확인 -> 필터 항목 확인"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // 아이템 dataList (BindItemset 용)
    let strItemDlt = '';
    strItemDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_item" baseNode="list" repeatNode="map">';
    strItemDlt += '<w2:columnInfo>';
    strItemDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strItemDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strItemDlt += '</w2:columnInfo>';
    strItemDlt += '<w2:data use="true"></w2:data>';
    strItemDlt += '</w2:dataList>';
    $p.data.create(strItemDlt);
    dlt_item.setJSON(scwin.itemList, false);

    // 바인딩 dataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="branch" name="branch" dataType="text"></w2:column>';
    strDlt += '<w2:column id="city" name="city" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "branch" : "본사", "city" : "SEL" },
        { "branch" : "영남지사", "city" : "BSN" },
        { "branch" : "수도권지사", "city" : "ICN" }
    ], false);

    // city Column 속성
    let attrCity = ' inputType="select" delimiter=":"';
    attrCity += (cFilterDisplayMode === '') ? '' : ' filterDisplayMode="' + cFilterDisplayMode + '"';

    // 아이템 : 정적 아이템(choices) / BindItemset(itemset nodeset="data:dlt_item")
    let strItems = '<w2:choices>';
    if (cItemType === "itemset") {
        strItems += '<w2:itemset nodeset="data:dlt_item"><w2:label ref="label"></w2:label><w2:value ref="value"></w2:value></w2:itemset>';
    } else {
        scwin.itemList.forEach(function (item) {
            strItems += '<w2:item><w2:label>' + item.label + '</w2:label><w2:value>' + item.value + '</w2:value></w2:item>';
        });
    }
    strItems += '</w2:choices>';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" useFilterList="true" style="width:500px;height:150px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column1" value="branch"></w2:column>';
    strTarget += '<w2:column width="330" style="" inputType="text" id="column2" value="city (select)" useFilter="true"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="branch" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="330" style="text-align:left;" id="city" value=""' + attrCity + '>' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// validation 1 : FilterList 필터 항목 텍스트
//  - FilterList 는 그리드 밖 클릭 시 닫히므로 DOM 대신 목록 컴포넌트(customFilterList) 의 데이터로 읽음
//  - 앞 2행(사용자필터 / 전체선택) 은 필터 항목이 아니므로 제외
scwin.btn_checkFilterItem_onclick = function () {
    let arr = [];
    if (target1.customFilterList) {
        target1.customFilterList.getAllData().slice(2).forEach(function (row) {
            arr.push("'" + row.id2 + "'");
        });
    }
    wf_body_bottom.getObj("scwin").setReturnValue("FilterList 항목 : " + (arr.length ? arr.join(" / ") : "열린 FilterList 없음"));
}
